<?php
class Session{public static function start(){if(session_status()===PHP_SESSION_NONE)session_start();}public static function set($k,$v){self::start();$_SESSION[$k]=$v;}public static function get($k,$d=null){self::start();return $_SESSION[$k]??$d;}public static function has($k){self::start();return isset($_SESSION[$k]);}public static function destroy(){self::start();session_destroy();}public static function flash($k,$m=null){self::start();if($m!==null){$_SESSION['_flash'][$k]=$m;return null;}if(isset($_SESSION['_flash'][$k])){$x=$_SESSION['_flash'][$k];unset($_SESSION['_flash'][$k]);return $x;}return null;}}
